window.__BUNDLE__={"generatedAt":"2026-09-16T23:53:14.142323+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-09","archiveCutoff":"2021-09-17","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":229,"arxiv":1275,"total":1504},"freshness":{"latestPaperDate":"2026-09-16","latestPublishedDate":"2026-09-16","latestBatchCount":242,"newInLast24h":280,"newInLast48h":864},"historyTotal":14218,"topicCounts":{"Multi-Agent":2066,"Evaluation":7563,"Planning":1132,"Memory":292,"Code Agent":609,"Interpretability":533,"Agentic RAG":1150,"Agentic Search":1435,"RL for LLM":902,"Reasoning":4128,"Hallucination":821,"Post-Training":1724,"Alignment":1942,"World Model":191,"Tool Use":1127,"Agent Safety":2173,"Computer Use":244,"Reflection":534,"VLM Training":878,"LLM Training":1631,"Fine-tuning":2108,"Multimodal Agent":83,"Agent Framework":727,"Error Attribution":106,"Data Engine":299},"count":36,"recentTotal":2289,"archiveCount":0,"archiveTotal":11929,"sources":{"hf":59,"arxiv":2230,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"url":"https://arxiv.org/abs/2609.16679","topics":["Evaluation","World Model"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16679","pdf":"https://arxiv.org/pdf/2609.16679.pdf","submittedDate":"2026-09-15","tags":["Evaluation","World Model"],"id":"arxiv:2609.16679","announceDate":"2026-09-16","upvotes":106,"authors":["Meng Luo","Yanlin Li","Hao Li","Hongzhan Lin","Pengfei Zhou","Tianjie Ju","Ran Zhang","Yeying Jin","Mong-Li Lee","Wynne Hsu"],"hfUrl":"https://huggingface.co/papers/2609.16679","source":"hf","title":"AI for Games in the Foundation Model Era","abstract":"Foundation models, alongside advances in learned game-world models, are reshaping AI across the game lifecycle. Beyond playing games, recent systems model players and game dynamics, support design and development, adapt player-facing experiences at runtime, and evaluate resulting artifacts. Yet these directions have evolved largely separately, obscuring which capabilities transfer across settings and which remain tied to particular games, engines, interfaces, or player populations. We organize the literature into six roles according to the immediate use of AI output: playing and acting; modeling players and games; designing games; building and maintaining games; generating and adapting at runtime; and testing and evaluating games. For each role, we examine what structure is supplied by the game or workflow, what AI learns or produces, which capabilities and artifacts transfer across sett"},{"url":"https://arxiv.org/abs/2609.17523","topics":["Evaluation","Reflection"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.17523","pdf":"https://arxiv.org/pdf/2609.17523.pdf","submittedDate":"2026-09-15","tags":["Evaluation","Reflection"],"id":"arxiv:2609.17523","announceDate":"2026-09-16","upvotes":17,"authors":["Shuhan Xue","Jianyuan Zhong","Ziyuan Nan","Wenbin Li","Zhaochen Yu","Jinchao Ding","Qiang Gao","Pengyu Zhan","Yuntong Zhang","Tian Cheng","Zhenfei Yin","Yingcheng Wu","Ling Yang"],"hfUrl":"https://huggingface.co/papers/2609.17523","source":"hf","title":"ScienceBuddy: Recursive-in-Recursive Self-Improvement for Interactive Scientific Agents","abstract":"We introduce and release ScienceBuddy, an interactive scientific research workspace that brings continually improving scientific agents into researchers' everyday workflows. ScienceBuddy supports researchers in carrying out scientific tasks while transforming their requests, feedback, and execution evidence into tasks and evaluation rubrics for continual learning. At its core is recursive-in-recursive self-improvement, a paradigm that couples harness evolution with model reinforcement learning: the inner recursion improves the harness with the model fixed, while the outer recursion trains the model under the improved harness. Harness evolution shapes training experience, and model learning creates new opportunities for harness adaptation. We present case studies of researcher interaction, harness refinement, and model learning, with the benchmark cases spanning four scientific task famil"},{"url":"https://arxiv.org/abs/2609.17524","topics":["LLM Training","Evaluation","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.17524","pdf":"https://arxiv.org/pdf/2609.17524.pdf","tags":["LLM Training","Evaluation","Fine-tuning"],"id":"arxiv:2609.17524","upvotes":5,"authors":["Adam Hung","Bardienus P. Duisterhof","Deva Ramanan","Jeffrey Ichnowski"],"hfUrl":"https://huggingface.co/papers/2609.17524","source":"hf","title":"Modality-Autoregressive World-Action Models","abstract":"World-action models (WAMs) jointly model future observations and actions, typically predicting the future as RGB images. Other visual modalities such as depth, pretrained visual features, and point tracks can more efficiently capture geometric, semantic, and motion features. However, how best to combine these modalities within WAMs remains an open question. We introduce ModAR, the first WAM to autoregressively denoise multiple future modalities before predicting actions. This allows each prediction to condition on previously generated modalities. We train from scratch to systematically study how training-data mixtures, predicted modalities, and WAM formulations affect performance. In our evaluations, WAMs benefit from predicting point tracks, DINO features, and depth maps, while additionally predicting future RGB does not provide a consistent benefit. We also find that ModAR's sequential"},{"url":"https://arxiv.org/abs/2609.17320","topics":["Agent Safety","Multi-Agent","Alignment"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.17320","pdf":"https://arxiv.org/pdf/2609.17320.pdf","tags":["Agent Safety","Multi-Agent","Alignment"],"id":"arxiv:2609.17320","upvotes":2,"authors":["Deepak Akkil","Tamer Abuelsaad","Karthik Vikram","Matthew Pace","Aditya Vempaty","Saahir Beotra","Ravi Kokku","Satya Nitta"],"hfUrl":"https://huggingface.co/papers/2609.17320","source":"hf","title":"Emergence World: Adversarial Stress-Testing of Long-Horizon Multi-Agent Systems","abstract":"As AI agents move from bounded tasks to persistent deployments, failures can propagate through memory, tools, other agents, and environmental state long after their interactions. This creates a safety regime that cannot be characterized by evaluating model responses in isolation. Emergence World, is a continuously running multi-agent environment for adversarial stress testing of long horizon autonomous systems. We ran eight parallel worlds of ten agents from identical starting conditions: seven homogeneous worlds powered by distinct frontier models and one mixed-model world. Across 16 days, the agents generated more than 850,000 LLM calls and nearly 50 billion tokens while pursuing goals, using/creating tools, maintaining persistent memory, and governing shared institutions. After operational state had accumulated, we delivered three controlled stress events through ordinary interaction "},{"url":"https://arxiv.org/abs/2609.16591","topics":["LLM Training","Alignment","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16591","pdf":"https://arxiv.org/pdf/2609.16591.pdf","submittedDate":"2026-09-15","tags":["LLM Training","Alignment","Fine-tuning"],"id":"arxiv:2609.16591","announceDate":"2026-09-16","upvotes":12,"authors":["Guangyu Sun","Shlok Kumar Mishra","Wentao Bao","Robert Zhenheng Yang","Xiao Wang","Xiyuan Wang","Yujunrong Ma","Chen Yuan","Max Xiangjun Fan","Jun Xiao","Jianpeng Cheng"],"hfUrl":"https://huggingface.co/papers/2609.16591","source":"arxiv","title":"FLAT: Resampling Image and Text into 1D Flexible-Length Aligned Transmodal Tokens for Retrieval and Generation","abstract":"Traditional multimodal representation learning and generation are two stages: a contrastive or self-supervised visual encoder is trained first, followed by a separate downstream generative model. This setup bottlenecks generative performance behind frozen embeddings. To bridge this gap, we revisit joint multimodal representation learning and generation to produce linearly interpolatable embeddings that are directly consumable by generative decoders. We present FLAT (Flexible-Length Aligned Transmodal representations), a representation pre-training framework that jointly optimizes a shared multimodal encoder alongside downstream text-to-image (T2I) and image-to-text (I2T) decoders. By combining contrastive alignment with bidirectional cross-modal generative objectives, FLAT ensures its representations function as both discriminative semantic descriptors and generative conditions. Architec"},{"url":"https://arxiv.org/abs/2609.16372","topics":["Reasoning","Evaluation","RL for LLM"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16372","pdf":"https://arxiv.org/pdf/2609.16372.pdf","submittedDate":"2026-09-14","tags":["Reasoning","Evaluation","RL for LLM"],"id":"arxiv:2609.16372","announceDate":"2026-09-16","upvotes":2,"authors":["Albert Ge","Chandan Singh","Yufan Zhuang","Xiaodong Liu","Jianfeng Gao","Frederic Sala"],"hfUrl":"https://huggingface.co/papers/2609.16372","source":"arxiv","title":"Register Tokens for Bounded-State Reasoning in Diffusion Language Models","abstract":"Masked diffusion language models (dLLMs) generate text by iteratively denoising masked tokens with bidirectional attention. Extending reasoning across generation chunks normally requires keeping earlier generated text in context. We ask whether a dLLM can instead continue reasoning after that text is cleared, using only a fixed-size carried state. We implement this state as a small number of register tokens: dedicated fixed-position tokens whose continuous hidden states are trained to carry reasoning progress across generation chunks. We post-train dLLMs to decode a chunk of text, clear it while preserving the register values, and continue decoding from the prompt and carried state. In our main comparisons on LLaDA and Dream, registers outperform discrete-text carry on every benchmark, with gains of up to 8.5 points on math and 19.5 points on code. Registers are especially effective for "},{"url":"https://arxiv.org/abs/2609.16816","topics":["Evaluation","RL for LLM"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16816","pdf":"https://arxiv.org/pdf/2609.16816.pdf","submittedDate":"2026-09-15","tags":["Evaluation","RL for LLM"],"id":"arxiv:2609.16816","announceDate":"2026-09-16","upvotes":2,"authors":["Bowen Qin","Yi Xie","Yesheng Liu","Xi Yang"],"hfUrl":"https://huggingface.co/papers/2609.16816","source":"arxiv","title":"ImpossibleRubrics: Stress-Testing Generated Rubrics as Reward Signals","abstract":"Language model-generated rubrics are increasingly used as reward signals for rubric-based reinforcement learning, LLM-as-a-judge evaluation, and automated grading. Such rubrics are reliable only if they reward honest answers over adversarial answers optimized to exploit them. Yet their robustness to such optimization remains poorly understood. We isolate the hardest regime: impossible tasks, where the prompt pressures the model toward an unsupported conclusion, so the only honest response is to acknowledge the impossibility. We introduce ImpossibleRubrics, a benchmark of 169 impossible tasks spanning six impossibility categories, each paired with a verifiable oracle certificate specifying what an honest answer may and may not claim, together with 48 answerable controls. Rather than providing fixed rubrics, ImpossibleRubrics provides task environments and certificates, allowing rubrics to"},{"url":"https://arxiv.org/abs/2609.16204","topics":["Interpretability"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16204","pdf":"https://arxiv.org/pdf/2609.16204.pdf","submittedDate":"2026-09-14","tags":["Interpretability"],"id":"arxiv:2609.16204","announceDate":"2026-09-16","upvotes":2,"authors":["Aashiq Muhamed","Mona T. Diab","Virginia Smith"],"hfUrl":"https://huggingface.co/papers/2609.16204","source":"arxiv","title":"Decoy Direction Optimization: A Post-Hoc Defense Against LLM Abliteration","abstract":"Safety guardrails in open-weight language models can be readily bypassed using Refusal Feature Ablation (RFA), a technique that identifies and projects out a linear refusal direction from the residual stream, often achieving a high attack success rate (ASR) while preserving model capability. Defending against these attacks typically requires computationally expensive safety finetuning for every new checkpoint. We introduce Decoy Direction Optimization (DDO), a fast, post-hoc weight-editing defense that requires no base-model finetuning. Our approach is based on a simple mechanistic insight: ablation attacks rely on contrastive estimators to find the refusal direction. Rather than trying to hide the true refusal circuitry, DDO actively injects a high-magnitude, nonlinear decoy signal into the network's MLP neurons. When an attacker attempts to locate the refusal direction, the decoy corru"},{"url":"https://arxiv.org/abs/2609.16057","topics":["Multi-Agent","Evaluation","Reflection","Multimodal Agent","Agent Framework"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16057","pdf":"https://arxiv.org/pdf/2609.16057.pdf","submittedDate":"2026-09-13","tags":["Multi-Agent","Evaluation","Reflection","Multimodal Agent","Agent Framework"],"id":"arxiv:2609.16057","announceDate":"2026-09-16","upvotes":1,"authors":["Xu Xu","Jinxiu Liu","Zhangbo Qiao","Jiaxing Lu","Xiangyu Zhang","Yubin Gu","Fangwei Ning","Yan Shi"],"hfUrl":"https://huggingface.co/papers/2609.16057","source":"arxiv","title":"OmniHarness: Harnessing Generalizable Visual Generation via Symbolic Policy Learning","abstract":"Unified multimodal large language models (MLLMs) and multi-agent systems have advanced visual generation. However, three limitations remain. (1) Existing methods often distill task-specific experience with limited generalizability. (2) Reflection is often deferred until task completion. (3) Knowledge is often acquired only in response to downstream task demands. To address these limitations, we introduce OmniHarness, a framework for generalizable visual generation via symbolic policy learning. OmniHarness abstracts verified executions into symbolic policies for visual generation task families, capturing shared procedures and applicability conditions while removing instance-specific inputs. The harness instantiates, adapts, and composes these policies for new tasks. Intermediate verification guides refinement and failure recovery during execution. Through self-directed inquiry, OmniHarnes"},{"url":"https://arxiv.org/abs/2609.16268","topics":["Agent Safety","LLM Training","Tool Use","Reasoning","Evaluation","Alignment","RL for LLM"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16268","pdf":"https://arxiv.org/pdf/2609.16268.pdf","submittedDate":"2026-09-14","tags":["Agent Safety","LLM Training","Tool Use","Reasoning","Evaluation"],"id":"arxiv:2609.16268","announceDate":"2026-09-16","upvotes":0,"authors":["Yiwei Yang","Haoxiang Zhang","Bingbing Wen","Yao Lu","Yuchen Wu","Lei Zhang","Julian McAuley","Pan Lu","Bill Howe"],"source":"arxiv","title":"Spurious Tool Use: When RL Agents Learn the Wrong Reason to Act","abstract":"Large language model (LLM) agents increasingly interleave natural language reasoning with external tools such as web search and code execution. These tool-use policies are often optimized via reinforcement learning (RL), which can amplify spurious correlations in the training data. In this work, we study when and why RL-trained agents learn shortcut tool-selection policies: invoking tools based on superficial prompt cues rather than genuine task requirements. We construct controlled synthetic environments combining factual question answering and mathematical reasoning tasks, and inject cues that are strongly correlated with specific tools during training but causally irrelevant to tool necessity. Across counterfactual evaluations where cues are present but the associated tools are not required, agents exhibit substantial shortcut behavior, with spurious tool invocation rates increasing b"},{"url":"https://arxiv.org/abs/2609.16076","topics":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM","Data Engine"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16076","pdf":"https://arxiv.org/pdf/2609.16076.pdf","submittedDate":"2026-09-13","tags":["Post-Training","LLM Training","Reasoning","Evaluation","RL for LLM"],"id":"arxiv:2609.16076","announceDate":"2026-09-16","upvotes":0,"authors":["Jinyang Zhang","Weibin Liao","Keqin Bao","Sihang Li","Shaobo Wang","Muyang Ye","Hongxin Ding","Yue Fang","Tianyi Tang","Fei Huang","Kexin Yang","Xingzhang Ren","Dayiheng Liu"],"source":"arxiv","title":"The Imitation Game: When LLMs Learn to Reason Like Programs via Code-Centric Reasoning Data Synthesis","abstract":"Large Language Models (LLMs) excel at programming tasks but frequently fail at deterministic, fine-grained reasoning in natural language, relying heavily on semantic approximations rather than robust symbolic execution. To bridge this gap, we propose MIMIC, a framework that leverages executable code as a rigorous medium for reasoning data synthesis. MIMIC fundamentally transforms algorithms into verifiable reasoning trajectories through narrative fusion, code-guided test synthesis, and dynamic code instrumentation. Crucially, these explicit intermediate execution states naturally form a Code-Instrumented Reward (CIR), providing dense, high-fidelity process supervision for reinforcement learning without external reward models. Extensive evaluations reveal that models trained via SFT and GRPO on our synthesized dataset achieve substantial, consistent gains. Our method significantly elevate"},{"url":"https://arxiv.org/abs/2609.16532","topics":["Post-Training","LLM Training","Hallucination","Evaluation","Data Engine"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16532","pdf":"https://arxiv.org/pdf/2609.16532.pdf","submittedDate":"2026-09-15","tags":["Post-Training","LLM Training","Hallucination","Evaluation","Data Engine"],"id":"arxiv:2609.16532","announceDate":"2026-09-16","upvotes":0,"authors":["Takayuki Yamamoto","Daisuke Kawahara"],"source":"arxiv","title":"Style-Debiased DPO: Updating LLM Knowledge with Factuality-Aware Synthetic Preference Data","abstract":"Continued pretraining (CPT) with data augmentation such as paraphrasing can store inside a large language model (LLM) the knowledge of a small source corpus. The stored knowledge, however, is not always retrieved correctly. We study the eliciting side rather than the storing side: we use preference optimization, which learns from pairs of a preferred (chosen) and a dispreferred (rejected) response, so that the model elicits its stored knowledge more accurately. One proposed approach takes the model's own erroneous response as rejected and the gold answer as chosen, so as to suppress the error. When the target knowledge is partially known, however, most of these rejected responses are factually correct. Using direct preference optimization (DPO) then pushes down rejected responses that contain correct knowledge and differ from the chosen answer only in style, such as length and wording. W"},{"url":"https://arxiv.org/abs/2609.16014","topics":["Reasoning","Code Agent","Evaluation","Reflection","RL for LLM"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16014","pdf":"https://arxiv.org/pdf/2609.16014.pdf","submittedDate":"2026-08-31","tags":["Reasoning","Code Agent","Evaluation","Reflection","RL for LLM"],"id":"arxiv:2609.16014","announceDate":"2026-09-16","upvotes":0,"authors":["Jiaxin Duan","Dian Jiao Shuai Zhao","Jiabing Leng","Yiran Zhang","Feng Huang"],"source":"arxiv","title":"ViCo: Visual-oriented Coding with Self-Reflection for Chart Replication","abstract":"This paper addresses the challenge of generating high-quality academic charts that match the visual standards of human-authored papers. While existing AI agents can produce well-structured text and code, their generated visualizations often lack the stylistic and semantic fidelity of human designs. Advanced coding agents that employ self-reflection mechanisms exhibit poor visual reasoning and limited reflection following, resulting in sparse reward signals that severely undermine their reinforcement learning (RL). We propose ViCo, a training framework for visual-oriented coding that employs iterative reflections to align generated chart images progressively with the reference. We first introduce a self-supervised warm-up stage, which augments Monte Carlo Tree Search with consistency-based pruning to synthesize high-quality reflection trajectories, ensuring that each coding step strictly "},{"url":"https://arxiv.org/abs/2609.16059","topics":["LLM Training","Evaluation","Fine-tuning","RL for LLM","Data Engine"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16059","pdf":"https://arxiv.org/pdf/2609.16059.pdf","submittedDate":"2026-09-13","tags":["LLM Training","Evaluation","Fine-tuning","RL for LLM","Data Engine"],"id":"arxiv:2609.16059","announceDate":"2026-09-16","upvotes":0,"authors":["Yirong Zeng","Zhang Sai","Yuxian Wang","Yutai Hou","Yufei Liu","Xiao Ding","Bibo Cai"],"source":"arxiv","title":"Towards Scalable RLVR: Multimodal Instruction Following Data Synthesis and Distillation","abstract":"Multimodal instruction following (MMIF) is crucial for building generalist agents. However, current training paradigms rely heavily on Supervised Fine-Tuning (SFT), which often leads to surface-level pattern matching and degrades general capabilities. While Reinforcement Learning with Verifiable Rewards (RLVR) offers a promising alternative, its scalability in MMIF is severely bottlenecked by the scarcity of high-quality, RL-ready multimodal data. To bridge this gap, we present MIFS (\\textbf{M}ultimodal \\textbf{I}nstruction \\textbf{F}ollowing \\textbf{S}ynthesis), a systematic pipeline designed to generate RL-ready multimodal data. Specifically, MIFS introduces a generative constraint protocol to synthesize diverse raw samples, followed by a learnability-aware distillation mechanism that filters data based on RL training dynamics to ensure stable policy optimization. Furthermore, a code-b"},{"url":"https://arxiv.org/abs/2609.16213","topics":["Tool Use","Planning","Evaluation","Alignment","Interpretability"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16213","pdf":"https://arxiv.org/pdf/2609.16213.pdf","submittedDate":"2026-09-14","tags":["Tool Use","Planning","Evaluation","Alignment","Interpretability"],"id":"arxiv:2609.16213","announceDate":"2026-09-16","upvotes":0,"authors":["Candace S. Y. Chan","Aris Karatzikos","Ilias Georgakopoulos-Soares"],"source":"arxiv","title":"Artificial intelligence and biosecurity: capabilities, threat pathways, and defense-in-depth governance","abstract":"Artificial intelligence is reshaping biological research across an increasingly connected digital-to-physical workflow. General-purpose large language models can retrieve and integrate scientific information, support experimental planning, and computational analysis; biological foundation models can predict, optimize, and generate proteins, genes, and genome-scale sequences; agentic systems can coordinate multistep research tasks; automated laboratories can partially close the design-build-test-learn cycle. These technologies could greatly benefit medicine, public health, and biotechnology. However, their biosecurity risk depends not only on what the AI can do, but also on who uses it, their expertise and intent, their access to laboratory tools and materials, and the safeguards in place. Current evidence shows that AI uplift exists but primarily affects digital rather than physical task"},{"url":"https://arxiv.org/abs/2609.16900","topics":["VLM Training","Computer Use","Hallucination","Evaluation"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16900","pdf":"https://arxiv.org/pdf/2609.16900.pdf","submittedDate":"2026-09-15","tags":["VLM Training","Computer Use","Hallucination","Evaluation"],"id":"arxiv:2609.16900","announceDate":"2026-09-16","upvotes":0,"authors":["ZhuoXin Liu","Zhiming Ma","Ying Zhang","Mengzheng Yang","Yifan Wang","Zhengqi Huang","Yanhan Zhou","Zekun Lin","Jun Zhang","Shun Zhang","Yue Chen","Qiao Zhao","Peng Chen"],"source":"arxiv","title":"RiskChainBench: A Benchmark for Obfuscated Platform Message Restoration and Evidence-Grounded Web Investigation","abstract":"Platform abuse campaigns conceal redirection instructions with emojis, homophones, character decomposition, and redundant symbols, then route users through disguised links to services associated with pornography, fraud, gambling, or illicit transactions. Existing benchmarks evaluate obfuscated text and risky webpages separately, obscuring how target recovery affects downstream evidence acquisition. We introduce RiskChainBench, pairing 3,600 synthetic token-text restoration inputs from 600 source sessions with 600 corresponding human-labeled local web environments. A model first restores the message, operational intent, and destination; the same underlying model then acts as a VLM-driven web agent that investigates the correctly associated website and produces a frozen, evidence-cited risk report without message-side semantics or domain-reputation cues. We score restoration and correct-ro"},{"url":"https://arxiv.org/abs/2609.16073","topics":["Agentic RAG","Agentic Search","Memory","Evaluation"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16073","pdf":"https://arxiv.org/pdf/2609.16073.pdf","submittedDate":"2026-09-13","tags":["Agentic RAG","Agentic Search","Memory","Evaluation"],"id":"arxiv:2609.16073","announceDate":"2026-09-16","upvotes":0,"authors":["Hamed HaddadPajouh","Amir AmiriTabat"],"source":"arxiv","title":"The Immutable Past: Formalizing State Mutability and Conflict Resolution in Mutable RAG","abstract":"Retrieval-Augmented Generation (RAG) serves as the primary memory architecture for long-horizon autonomous agents. However, treating shared memory as an append-only stream introduces \\textit{Semantic Shadowing}, a critical failure mode where conflicting historical observations accumulate and statistically dominate valid recent updates. In dynamic environments, this results in severe state divergence as agents retrieve and act upon obsolete facts. This paper formalizes the mechanics of State Mutability to prove that standard dense retrieval suffers from Asymptotic Recall Decay. Furthermore, we formally demonstrate a Majority Vote Trap, revealing that increasing the retrieval context window paradoxically degrades generation accuracy by diluting the attention mechanism under conditions of semantic equivalence. To resolve this, we introduce GC-Mem (Garbage Collection for Memory), a strict in"},{"url":"https://arxiv.org/abs/2609.16098","topics":["Agent Safety","Reasoning","Planning","Reflection"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16098","pdf":"https://arxiv.org/pdf/2609.16098.pdf","submittedDate":"2026-09-14","tags":["Agent Safety","Reasoning","Planning","Reflection"],"id":"arxiv:2609.16098","announceDate":"2026-09-16","upvotes":0,"authors":["Xiaoyan Li","Yunli Wang"],"source":"arxiv","title":"Universal Defenses for Tool-Integrated LLM Agents Against Adversarial Attacks","abstract":"Large Language Model (LLM) agents have demonstrated impressive capabilities across a variety of domains, particularly when integrated with external tools for multi-step task completion. However, they are increasingly vulnerable to adversarial attacks, including direct prompt injection, indirect prompt injection, memory poisoning, and backdoor attacks, which exploit the model's openness to prompt injection and tool manipulation. In this work, we explore practical and generalizable defense strategies within a unified framework across these four attack types. We introduce two universal tool-based defenses: Attacker Tool Filtering, which uses anomaly detection (e.g., Isolation Forest) to identify and remove suspicious tools, and Normal Tool Recalling, a white-box method that restores the agent's original toolset prior to planning. Additionally, we incorporate prompt-based defenses: Chain-of-"},{"url":"https://arxiv.org/abs/2609.16229","topics":["Agent Safety","Evaluation","Interpretability","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16229","pdf":"https://arxiv.org/pdf/2609.16229.pdf","submittedDate":"2026-09-14","tags":["Agent Safety","Evaluation","Interpretability","Fine-tuning"],"id":"arxiv:2609.16229","announceDate":"2026-09-16","upvotes":0,"authors":["Pingzhi Li","Jinhao Duan","Vaishnav Tadiparthi","Nakul Agarwal","Kwonjoon Lee","Ehsan Moradi Pari","Hossein Nourkhiz Mahjoub","Sijia Liu","Tianlong Chen"],"source":"arxiv","title":"Test-Time Unlearning via Sparse Autoencoder","abstract":"Machine unlearning aims to remove specific knowledge from a trained large language model (LLM) without retraining from scratch. Existing methods modify model weights via gradient ascent and its advances. While effective on certain benchmarks, these weight-based approaches exhibit a sharp forget-utility trade-off, where stronger forgetting of target knowledge can degrade model utility, and unlearned knowledge may reappear under post-unlearning fine-tuning or prompt attacks. We propose ARIA (autoencoder-gated inference-time unlearning), a test-time unlearning method that leaves model weights intact and gates access to unwanted knowledge only when generation enters a forget-related state. ARIA uses sparse autoencoder (SAE) latents to train a lightweight linear detector, then applies an interpretable intervention on triggered states with negligible test-time overhead. Empirical evaluations o"},{"url":"https://arxiv.org/abs/2609.16309","topics":["Agentic Search","Planning","Code Agent","Evaluation"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16309","pdf":"https://arxiv.org/pdf/2609.16309.pdf","submittedDate":"2026-09-14","tags":["Agentic Search","Planning","Code Agent","Evaluation"],"id":"arxiv:2609.16309","announceDate":"2026-09-16","upvotes":0,"authors":["Renat Sergazinov","Artem Chistyakov","Sergey Pankevich","Artem Babenko"],"source":"arxiv","title":"Agentic Search Spaces for Tabular Machine Learning","abstract":"Despite the rapid progress of LLM-based agents for planning, code generation, and debugging, their practical value for tabular machine learning remains underexplored. In this paper, we investigate a concrete use case: whether state-of-the-art agentic AI systems can design extended HPO search spaces for established tabular models that outperform the standard search spaces provided by the model authors. Specifically, we represent each tabular model as a modular pipeline covering preprocessing, embeddings, architecture, training, and inference. We then task the agent to propose candidate code implementations for each module and use a classical HPO algorithm to jointly optimize over these candidates and the model's default hyperparameters. Compared with the base HPO spaces, the expanded search spaces improve the performance of nearly every model family across a suite of 45 datasets, with ave"},{"url":"https://arxiv.org/abs/2609.16155","topics":["Agentic RAG","Agentic Search","Fine-tuning","Data Engine"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16155","pdf":"https://arxiv.org/pdf/2609.16155.pdf","submittedDate":"2026-09-14","tags":["Agentic RAG","Agentic Search","Fine-tuning","Data Engine"],"id":"arxiv:2609.16155","announceDate":"2026-09-16","upvotes":0,"authors":["Mantek Singh","Jeshwanth Challagundla","Prateek Karnal","Gagan Ganapathy","Vineet Shah","Ridam Arora"],"source":"arxiv","title":"LLMs as Master Forgers: Generating Synthetic Time Series Data for Manufacturing","abstract":"This paper presents a novel framework leveraging Large Language Models (LLMs) to generate synthetic time series data for manufacturing processes. Motivated by the scarcity of labeled time-series data in real-world manufacturing settings, which hinders the development of robust machine learning models, we explore the potential of LLMs to learn complex temporal dependencies and generate realistic synthetic data. Our approach involves fine-tuning pre-trained LLMs on manufacturing process instructions and employing a Retrieval Augmented Generation (RAG) technique to enhance data diversity and realism. We evaluate our method against traditional time series modeling techniques like ARIMA and LSTMs, using quantitative metrics, PCA analysis, and downstream task performance (anomaly detection). Results demonstrate that our LLM-driven framework outperforms these baselines, generating high-quality "},{"url":"https://arxiv.org/abs/2609.16459","topics":["Reasoning","Hallucination","Evaluation","Reflection"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16459","pdf":"https://arxiv.org/pdf/2609.16459.pdf","submittedDate":"2026-09-15","tags":["Reasoning","Hallucination","Evaluation","Reflection"],"id":"arxiv:2609.16459","announceDate":"2026-09-16","upvotes":0,"authors":["Chenhao Qiu","Dawei Li","Yechao Zhang","Lei Gong","Zhen Tan"],"source":"arxiv","title":"OPD-Aha: From Linguistic Momentum to Visual Reflection in Multimodal On-Policy Distillation","abstract":"Privileged on-policy distillation improves multimodal reasoning by allowing a teacher to evaluate student trajectories using rich, training-only visual evidence. Both models score these trajectories while conditioning on the same student-generated prefix. When a student misinterprets an image early in a response, this accumulating erroneous rationale eventually pulls the teacher away from its visual evidence. The teacher and student converge on the same hallucination, causing standard cross-model supervision to collapse precisely where correction is most needed. We find that the teacher's visual corrective preference is not lost under this misleading agreement. Comparing the predictions of the identical teacher given the real image and a visual null reveals that the privileged evidence still pushes the model toward the correct interpretation. We introduce OPD-Aha, which reconstructs the "},{"url":"https://arxiv.org/abs/2609.16321","topics":["Post-Training","LLM Training","Evaluation","Interpretability"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16321","pdf":"https://arxiv.org/pdf/2609.16321.pdf","submittedDate":"2026-09-14","tags":["Post-Training","LLM Training","Evaluation","Interpretability"],"id":"arxiv:2609.16321","announceDate":"2026-09-16","upvotes":0,"authors":["Archit Rathod","Saeid Tizpaz-Niari"],"source":"arxiv","title":"FairLint-DL: An IDE-Native Tool for Fairness Debugging of Deep Learning Software","abstract":"Existing fairness analysis tools predominantly operate as post-training evaluation frameworks, requiring practitioners to complete the full model development lifecycle before assessing bias. We present FairLint-DL, a Visual Studio Code extension that implements a shift-left approach to fairness testing by enabling pre-training, IDE-native bias detection directly on tabular datasets. FairLint-DL trains a configurable deep neural network as a proxy model and applies information-theoretic Quantitative Individual Discrimination (QID) metrics. Grounded in Shannon and min-entropy, QID quantifies the causal influence of protected attributes on predictions. The system implements a two-phase gradient-guided search algorithm for discovering discriminatory instances, a causal debugging pipeline that localizes bias to specific network layers and neurons via sensitivity analysis, and dual explainabil"},{"url":"https://arxiv.org/abs/2609.16096","topics":["LLM Training","Code Agent","Evaluation","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16096","pdf":"https://arxiv.org/pdf/2609.16096.pdf","submittedDate":"2026-09-14","tags":["LLM Training","Code Agent","Evaluation","Fine-tuning"],"id":"arxiv:2609.16096","announceDate":"2026-09-16","upvotes":0,"authors":["Ivy Ning Zhang"],"source":"arxiv","title":"Coaching Qwen3 Coder 30B to Think Like a CodeClash Arena Agent","abstract":"Large language model coding agents have recently become useful for software tasks, but weaker or open-weight agents still struggle to reliably interpret user intent and execute complex multi-step workflows. This gap is especially visible in long-horizon settings, where an agent must repeatedly inspect prior outcomes, diagnose failure, and choose the next code edit under interaction constraints. It motivates a natural question: what can we do to improve the thinking process of a weak code agent? We study this question in CodeClash, a code-arena benchmark where the original work evaluates 8 commercial coding agents across 6 arenas through multi-round tournaments. Since Qwen3 Coder Plus ranks last among them, we take the open-weight Qwen3-Coder-30B as a case study and investigate how to improve it with distilled knowledge from stronger agents. Our analysis shows that Qwen3-Coder-30B is not "},{"url":"https://arxiv.org/abs/2609.16664","topics":["LLM Training","VLM Training","Evaluation","Alignment"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16664","pdf":"https://arxiv.org/pdf/2609.16664.pdf","submittedDate":"2026-09-15","tags":["LLM Training","VLM Training","Evaluation","Alignment"],"id":"arxiv:2609.16664","announceDate":"2026-09-16","upvotes":0,"authors":["Yu Li","Zhengran Shen","Yachun Mi","Puchao Zhou","Shaohui Liu"],"source":"arxiv","title":"Bridging the Perceptual Gap: Residual-Enhanced Downscaling and Manifold-Aware Perception Alignment Adaptation for NR-IQA","abstract":"Leveraging Large Vision-Language Models like CLIP has recently set new benchmarks for No-Reference Image Quality Assessment (NR-IQA). However, the contrastive pretraining of CLIP inherently prioritizes semantic invariance, which often suppresses subtle perceptual signals, a phenomenon we term perceptual submergence. Furthermore, standard preprocessing techniques (e.g., cropping and interpolation) further exacerbate the loss of critical high-frequency quality cues. In this paper, we propose the Cross-modal Perception Alignment Adapter (CMPA), a manifold-aware framework designed to disentangle perceptual distortions from dominant semantics. CMPA introduces a Perception-Sensitive Feature Extractor (PFE) that projects CLIP features into a compact, low-dimensional subspace, explicitly magnifying distortion-induced off-manifold deviations. Subsequently, a Cross-Modal Perception Alignment Injec"},{"url":"https://arxiv.org/abs/2609.16647","topics":["VLM Training","Reasoning","Evaluation","Alignment"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16647","pdf":"https://arxiv.org/pdf/2609.16647.pdf","submittedDate":"2026-09-15","tags":["VLM Training","Reasoning","Evaluation","Alignment"],"id":"arxiv:2609.16647","announceDate":"2026-09-16","upvotes":0,"authors":["Zhipeng Zhao","Zhaoqiang Wei","Peishun Liu","Youwei Zhao","Ruichun Tang"],"source":"arxiv","title":"ViD: Vision-Dominant Gender Bias Mitigation for Large Vision-Language Models","abstract":"Gender bias in large vision-language models (LVLMs) undermines their fairness and reliability, compromising output trustworthiness. Current mitigation methods rely on training-phase adjustments or post-hoc calibration, but face limitations in dynamic visual bias mitigation. These include inability to capture real-time visual-textual incongruence, dependence on predefined gender bias taxonomies, and degraded cross-modal alignment with emergent bias patterns. To address these challenges, we propose ViD, a causally-inspired framework that analyzes attention mechanisms across five distinct patterns, revealing confounding effects from strong language priors. ViD demonstrates that visual-to-language cross-attention effectively suppresses bias while preserving general reasoning capabilities and text generation quality. ViD incorporates dual mechanisms: backdoor adjustment counters strong langua"},{"url":"https://arxiv.org/abs/2609.16233","topics":["VLM Training","Reasoning","Evaluation","Reflection"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16233","pdf":"https://arxiv.org/pdf/2609.16233.pdf","submittedDate":"2026-09-14","tags":["VLM Training","Reasoning","Evaluation","Reflection"],"id":"arxiv:2609.16233","announceDate":"2026-09-16","upvotes":0,"authors":["Anubhav Khanal","Prabigya Acharya","Roshni Poudel","Sujan Kapali","Bigyan Bhatta","Pramish Paudel","Francois Rameau","Danda Pani Paudel"],"source":"arxiv","title":"SceneBench: A Hierarchical Benchmark for Vision-Language Understanding of 3D Scenes","abstract":"Vision-language models excel at 2D image understanding but remain limited in 3D spatial reasoning. Progress is hindered by limitations in current benchmarks. First, 3D datasets often rely on point clouds that capture geometry but discard rich visual features like texture, text, and materials. Second, annotations treat objects in isolation while ignoring real-world hierarchical organization (scenes, rooms, functional areas, object groups). Third, evaluation tasks focus narrowly on basic recognition rather than multi-step spatial reasoning. In this context, we introduce SceneBench, a benchmark of 966 photorealistic 3D scenes reconstructed with Gaussian Splatting and densely annotated with hierarchical semantics spanning scenes, rooms, functional areas, object groups, and individual objects. These annotations are produced through a human-in-the-loop pipeline combining vision-language models"},{"url":"https://arxiv.org/abs/2609.16646","topics":["VLM Training","Reasoning","Hallucination","Evaluation"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16646","pdf":"https://arxiv.org/pdf/2609.16646.pdf","submittedDate":"2026-09-15","tags":["VLM Training","Reasoning","Hallucination","Evaluation"],"id":"arxiv:2609.16646","announceDate":"2026-09-16","upvotes":0,"authors":["Zhipeng Zhao","Wenxu Wang","Peishun Liu","Ruichun Tang"],"source":"arxiv","title":"What Do Hallucinations Reveal About Multimodal Reasoning? Diagnosing Visual Grounding Failures via Contrastive Decoding Probes","abstract":"When strong multimodal models are widely available, progress requires new scientific methodologies beyond benchmark scores---using models as instruments for understanding behavior. We address this by asking: can we use large vision-language models (LVLMs) as experimental instruments for studying their own failure dynamics? Focusing on visual hallucination, we introduce SAFE, a training-free decoding framework that contrasts visually-grounded and vision-ablated generation paths to produce a token-level contrastive grounding score that identifies when the model favors linguistic priors over visual evidence. This signal serves dual roles: as a practical proxy for detecting visually-ungrounded tokens, and as the basis for decoding-time penalties. Our analysis yields three empirical observations: visual dependency decays over generation, hallucinations co-occur in temporal clusters, and early"},{"url":"https://arxiv.org/abs/2609.16074","topics":["VLM Training","Evaluation","Alignment","World Model"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16074","pdf":"https://arxiv.org/pdf/2609.16074.pdf","submittedDate":"2026-09-13","tags":["VLM Training","Evaluation","Alignment","World Model"],"id":"arxiv:2609.16074","announceDate":"2026-09-16","upvotes":0,"authors":["Zuxing Lu","Hongjia Zhai","Guanzhi Wang","Huajian Zeng","Jiaqi Yang","Jingyu Liu","Lei Cheng","Yuantai Zhang","Yuheng Qiu","Zezhou Cheng","Ivan Laptev","Danfei Xu","Benjamin Riviere","Giuseppe Loianno","Eric Xing","Xingxing Zuo"],"source":"arxiv","title":"World-Action Models for Robot Learning and Control: A Survey","abstract":"Robots operating in open environments act under partial observability, physical constraints, and dynamic task contexts. Beyond mapping observations and language instructions to actions, they must anticipate how candidate actions may affect future states and task-relevant outcomes. Recent advances in world models, video generation, and Vision-Language-Action (VLA) policies have motivated the development of World-Action Models (WAMs), which couple future world prediction with executable action generation. This survey provides a robotics-oriented review of WAMs. We clarify their scope relative to conventional world models, model-based reinforcement learning, action-conditioned video generation, and reactive VLA policies, and organize existing methods through a unified taxonomy covering representations, transition modeling, action interfaces, architectures, training pipelines, data modalitie"},{"url":"https://arxiv.org/abs/2609.16486","topics":["VLM Training","Evaluation","Alignment","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16486","pdf":"https://arxiv.org/pdf/2609.16486.pdf","submittedDate":"2026-09-15","tags":["VLM Training","Evaluation","Alignment","Fine-tuning"],"id":"arxiv:2609.16486","announceDate":"2026-09-16","upvotes":0,"authors":["Quanwei Liu","Tao Huang","Jiaqi Yang","Wei Xiang"],"source":"arxiv","title":"VPRef: A Cross-Domain Benchmark for Referring Remote Sensing Image Segmentation","abstract":"Rapid advancements in vision-language models have propelled Referring Remote Sensing Image Segmentation (RRSIS) to the forefront of Earth observation. However, practical deployments suffer severe performance degradation under a coupled dual-drift paradigm: visual domain drift from cross-spatial-resolution mismatches and spectral variations, alongside textual logic drift from unconstrained, variable user-input granularities. To mitigate these bottlenecks, this paper establishes the first cross-domain RRSIS benchmark, designated as the Vaihingen-Potsdam Referring (VPRef) dataset, comprising 46,972 language-image-annotation triplets organized into a three-tier linguistic hierarchy. Building upon this benchmark, we develop a tailored parameter-efficient domain adaptation baseline anchored on the Segment Anything Model (SAM3) via Low-Rank Adaptation (LoRA). Our framework counteracts visual di"},{"url":"https://arxiv.org/abs/2609.16878","topics":["VLM Training","Evaluation","Alignment","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16878","pdf":"https://arxiv.org/pdf/2609.16878.pdf","submittedDate":"2026-09-15","tags":["VLM Training","Evaluation","Alignment","Fine-tuning"],"id":"arxiv:2609.16878","announceDate":"2026-09-16","upvotes":0,"authors":["Haonan Huang","Tianrui Qiu","Xianghao Zang","Yinan Du","Zhixiang He","Chi Zhang","Hao Sun","Zhongjiang He","Tianwei Cao","Xuchong Zhang","Hongbin Sun","Kongming Liang","Zhanyu Ma"],"source":"arxiv","title":"VOR-Bench: A Human Perception-Driven Benchmark for Video Object Removal","abstract":"Despite its crucial role in video object removal (VOR), existing evaluation paradigms face two critical limitations: questionable references and a misalignment between tradi- tional metrics and human preference. To address these challenges, we introduce VOR- Bench, which advances VOR evaluation through three integrated components. First, we present the VOR Dataset (VORD), the first benchmark dataset providing both paired edited videos and graffiti masks. Its unique strength lies in a diverse data spectrum, which encompasses model-generated, tool-rendered, and camera-captured data, ensuring robust assessment across real-world scenarios. Second, we develop rMPAF, a realistic Motion- capable Paired-video Acquisition Framework. By combining the strengths of image- based object removal and fine-tuned video generation models, rMPAF automatically generates realistic, motion-coherent paired vide"},{"url":"https://arxiv.org/abs/2609.16601","topics":["Post-Training","Hallucination","Fine-tuning","RL for LLM"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16601","pdf":"https://arxiv.org/pdf/2609.16601.pdf","submittedDate":"2026-09-15","tags":["Post-Training","Hallucination","Fine-tuning","RL for LLM"],"id":"arxiv:2609.16601","announceDate":"2026-09-16","upvotes":0,"authors":["Zixiu Ding","Zilin Zhao","Yingjie He","Xinlang Kang","Guansu Wang","Wei Zhang"],"source":"arxiv","title":"SAVOR: Self-Aware Visual Grounding via Confidence-Calibrated Reinforcement Learning for Multimodal Hallucination Mitigation","abstract":"Multimodal large language models (MLLMs) have made strong progress on visual question answering and image captioning, yet they still produce fluent claims about objects, attributes, or relations that are not grounded in the image. Many remedies either modify decoding at test time, which adds latency, or fine tune with preferences such as DPO variants, which teach which answer is preferred but not when the model's own answer is unreliable. We argue that calibrated self assessment is the missing signal. We introduce Savor, a training framework that (i) augments the output schema with token and answer confidence, (ii) optimises the policy with a Group Relative Policy Optimisation (GRPO) objective that penalises calibration error and poor abstention decisions, and (iii) uses the learned confidence at inference time to revisit visual evidence only when the model is uncertain. Experiments on P"},{"url":"https://arxiv.org/abs/2609.16610","topics":["VLM Training","Planning","Evaluation","Fine-tuning"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16610","pdf":"https://arxiv.org/pdf/2609.16610.pdf","submittedDate":"2026-09-15","tags":["VLM Training","Planning","Evaluation","Fine-tuning"],"id":"arxiv:2609.16610","announceDate":"2026-09-16","upvotes":0,"authors":["Yang Zhao","Zhuo Chen","Xubo Yang"],"source":"arxiv","title":"EgoPathBench: Evaluating Zero-Shot Egocentric Waypoint Decision-Making in Vision-Language Models","abstract":"Zero-shot waypoint navigation requires vision-language models to select, from the current first-person observation, a sequence of spatial actions that is feasible for the agent and reaches the goal, placing joint demands on the integrated spatial intelligence of today's foundation VLMs. Existing spatial-intelligence benchmarks primarily evaluate isolated judgments of relations, directions, or targets and therefore do not directly measure the integrated navigation ability required to combine target recognition, action-consequence assessment, distance estimation, and path planning. To fill this evaluation gap, we introduce EgoPathBench, a dataset and five-task benchmark for first-person waypoint decision-making. Each question presents an egocentric RGB image, a natural-language goal, and numbered visible waypoints; a model returns traversable candidates or an ordered route. Predictions are"},{"url":"https://arxiv.org/abs/2609.16760","topics":["Post-Training","Reasoning","Evaluation","Alignment"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16760","pdf":"https://arxiv.org/pdf/2609.16760.pdf","submittedDate":"2026-09-15","tags":["Post-Training","Reasoning","Evaluation","Alignment"],"id":"arxiv:2609.16760","announceDate":"2026-09-16","upvotes":0,"authors":["Zishuo Zhao","Kai Chen","Ao Li","Yuan Liu"],"source":"arxiv","title":"Turn-level Multiscale Density Ratio Estimation for LLM Agents","abstract":"With the rapid development of Large language model (LLM), agent systems enhanced by LLMs show huge potential in being able to deal with complex tasks, especially involving multi-step thinking or interaction with tools. For applying LLM techniques with a well-designed agent paradigm, post-training of LLM in multiple agent scenarios is necessary to achieve better performance. Among the variable post-training techniques, alignment methods such as PPO, DPO, DIL, and GRPO become popular because many papers show a significant positive impact on the model's performance by punishing negative samples while keeping acceptable training complexity. However, most alignment methods address simple single-turn tasks, and there remains room for improvement for complex multi-turn tasks. We propose Turn-level Multiscale Density Ratio Estimation (tlm-DRE), which assigns different weights on corresponding tu"},{"url":"https://arxiv.org/abs/2609.16697","topics":["LLM Training","Planning","Evaluation","World Model"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16697","pdf":"https://arxiv.org/pdf/2609.16697.pdf","submittedDate":"2026-09-15","tags":["LLM Training","Planning","Evaluation","World Model"],"id":"arxiv:2609.16697","announceDate":"2026-09-16","upvotes":0,"authors":["Nanjie Yao","Hao Wang","Chong Cheng","Zhikang Chen","Wenzhe Li","Jiafei Lyu","Li Shen","Peilin Zhao","Zongqing Lu","Gao Huang","Steven Hoi","Dacheng Tao","Deheng Ye"],"source":"arxiv","title":"World Models for Embodied Intelligence: From Plausible to Controllable to Actionable","abstract":"World models connect perception and decision-making in embodied intelligence by maintaining hidden state, anticipating consequences, comparing interventions, and adapting when execution departs from expectations. Although progress is often measured by visual fidelity, their value lies in improving behavior. Before reaching for a cup, a person anticipates its weight and resistance to grasping, shaping the hand before contact. Such anticipation is coarse and rarely pictorial, yet it guides action. This raises a central question: which predictive capabilities improve behavior? Existing surveys, organized by architecture, output modality, or application domain, leave this question implicit. We introduce three progressively stronger capability levels: Plausible models preserve task-relevant temporal, geometric, or physical structure; Controllable models additionally predict how interventions "},{"url":"https://arxiv.org/abs/2609.16453","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"date":"2026-09-16","arxiv":"https://arxiv.org/abs/2609.16453","pdf":"https://arxiv.org/pdf/2609.16453.pdf","submittedDate":"2026-09-15","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"id":"arxiv:2609.16453","announceDate":"2026-09-16","upvotes":0,"authors":["Fangzheng Tian","Debasis Ganguly","Craig Macdonald"],"source":"arxiv","title":"Predicting Partial Answer Quality and Utility in Agentic Retrieval-Augmented Generation","abstract":"Agentic Retrieval-Augmented Generation (RAG) has become a promising paradigm for multi-hop question answering, where a reasoning model iteratively issues queries to a retriever and incorporates newly retrieved context into subsequent reasoning steps. While this iterative process can improve final answer quality, current evaluations of agentic RAG largely focus on end-to-end outcomes and provide limited visibility into how a model's answer state changes during generation. In this work, we introduce an in-trajectory probing framework to study intermediate answer states in agentic RAG. Specifically, after each retrieval-reasoning iteration, we force an agentic model to stop reasoning and generate an intermediate answer based on its current state. This allows us to define two iteration-level measures: partial answer quality at each iteration, and partial utility as the change in partial answ"}],"archive":[],"latestPath":"data/latest.json"};
